pub trait View { fn query(&self) -> String; fn show_total(&mut self, total: f64); }
pub struct Presenter<'a> {
    view: &'a mut dyn View,
    model: Model,
}
impl Presenter<'_> {
    pub fn query_changed(&mut self) {
        let total = self.model.total(&self.view.query());
        self.view.show_total(total);
    }
}

pub struct Presenter<V: View> { view: V, model: Model }
impl<V: View> Presenter<V> {
    pub fn query_changed(&mut self) {
        let total = self.model.total(&self.view.query());
        self.view.show_total(total);
    }
}
